			dw glyph_65, glyph_73, glyph_74, glyph_20, glyph_6F, glyph_6E, glyph_20, glyph_43
			dw glyph_50, glyph_43, glyph_20, glyph_6D, glyph_69, glyph_6E, glyph_69, glyph_6D
			dw glyph_61, glyph_6C, glyph_20, glyph_66, glyph_69, glyph_72, glyph_6D, glyph_77
			dw glyph_61, glyph_72, glyph_65, 1, 0		; "AMSDOS test on CPC minimal firmware\n"

			; main.bas 18: Print "Devices "; FileSystem.Devices(); " - using "; FileSystem.CurrentDevice()
			dw fn_filesystem_devices, var_filesystem_devices_devices
			dw kw_printzoscii
			dw glyph_44, glyph_65, glyph_76, glyph_69, glyph_63, glyph_65, glyph_73, glyph_20
