			dw kw_printstrvar, var_filesystem_devices_devices
			dw fn_filesystem_currentdevice, var_filesystem_currentdevice_currentdevice
			dw kw_printzoscii
			dw glyph_20, glyph_2D, glyph_20, glyph_75, glyph_73, glyph_69, glyph_6E, glyph_67
			dw glyph_20, 0		; " - using "
			dw kw_printstrvar, var_filesystem_currentdevice_currentdevice
			dw kw_printnl

			; main.bas 19: Print "Volumes "; FileSystem.Volumes(); " - using "; FileSystem.CurrentVolume()
			dw fn_filesystem_volumes, var_filesystem_volumes_volumes
			dw kw_printzoscii
			dw glyph_56, glyph_6F, glyph_6C, glyph_75, glyph_6D, glyph_65, glyph_73, glyph_20
			dw 0		; "Volumes "
			dw kw_printstrvar, var_filesystem_volumes_volumes
			dw fn_filesystem_currentvolume, var_filesystem_currentvolume_currentvolume
			dw kw_printzoscii
			dw glyph_20, glyph_2D, glyph_20, glyph_75, glyph_73, glyph_69, glyph_6E, glyph_67
			dw glyph_20, 0		; " - using "
			dw kw_printstrvar, var_filesystem_currentvolume_currentvolume
			dw kw_printnl

			; main.bas 20: Wait
			dw p_wait_c

			; main.bas 22: For i = 0 To 9 : a(i) = 1000 - i * 50 : Next
			dw kw_ztov, var_i
for1_t:
			dw kw_mulvl, var_i, 50, tmp2
			dw kw_sublv, 1000, tmp2, tmp1
			dw kw_aset, arr_a, var_i, tmp1
			dw kw_next1l_n, var_i, 9, for1_t
for1_e:

			; main.bas 23: r = FileSystem.Save("AMS1.DAT", VarPtr(a), 20)
			dw fn_filesystem_save, str1, vp_arr_a, lit_20, var_r

			; main.bas 24: Print "Save AMS1.DAT:"; r
			dw kw_printzoscii
