			dw glyph_31, glyph_2E, glyph_44, glyph_41, glyph_54, glyph_3A, 0		; "Save AMS1.DAT:"
			dw kw_printint, var_r
			dw kw_printnl

			; main.bas 25: r = FileSystem.Load("AMS1.DAT", VarPtr(b), 20)
