			; main.bas 48: r = FileSystem.Save("AMS3.DAT", VarPtr(a), 20)
			dw fn_filesystem_save, str8, vp_arr_a, lit_20, var_r

			; main.bas 49: Print "Save B:AMS3.DAT:"; r
			dw kw_printzoscii
