			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do6_e
			dw do6_t_go
do6_e:

			; main.bas 62: Do : Frame : Loop Until Inkey <> 0
do7_t:
			dw kw_frame
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do7_t
do7_e:
			dw p_wait_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

ch2_e_go:			ld sp, ch2_e
			jp ntc_xn
do3_t_go:			ld sp, do3_t
			jp ntc_xn
do6_t_go:			ld sp, do6_t
			jp ntc_xn

p_wait_c:		; call wait (normal)
			ld (p_wait_rs), sp
			ld sp, p_wait
			jp ntc_xn
p_wait_r:		; end of wait
			ld sp, (p_wait_rs)
			jp ntc_xn

